/bin/bash -lc "node <<'NODE'
const fs=require('fs');
const path=require('path');
const base=process.env.TMPDIR;
function decode(s){return s.replace(/&amp;/g,'&').replace(/&#39;|&#x27;|&#039;/g,\"'\").replace(/&nbsp;/g,' ').replace(/&ndash;/g,'–').replace(/&mdash;/g,'—').replace(/&rsquo;/g,'’').replace(/&ldquo;|&rdquo;/g,'\"').replace(/&lt;/g,'<').replace(/&gt;/g,'>');}
function text(s){return decode(s.replace(/<script[\\s\\S]*?<\\/script>/gi,' ').replace(/<style[\\s\\S]*?<\\/style>/gi,' ').replace(/<["'^>]+>/g,'"' ')).replace(/[\\t\\r\\n ]+/g,' ').trim();}
function parsePage(file){const html=fs.readFileSync(path.join(base,file),'utf8'); const hs=[...html.matchAll(/<h[3-6]["'^>]*>(['"\\s\\S]*?)<\\/h[3-6]>/gi)]; const out=[]; for(let i=0;i<hs.length;i++){const head=text(hs[i][1]); if("'!/''^'"\\d+\\.\\s*/.test(head)) continue; const name=head.replace(/"'^'"\\d+\\.\\s*/,'').trim(); const start=hs[i].index+hs[i][0].length; const end=(hs[i+1]&&hs[i+1].index)||html.length; const block=text(html.slice(start,end)); let duration=null, eligibility=null; const dm=block.match(/Duration:\\s*(.*?)(?=Eligibility:|Selection Procedure:|Tuition Fee:|Caution Money:|Apply Online|View Details|"'$)/i); if(dm) duration=dm[1].trim()||null; const em=block.match(/Eligibility:'"\\s*(.*?)(?=Selection Procedure:|Tuition Fee:|Caution Money:|Apply Online|View Details|"'$)/i); if(em) eligibility=em[1].trim()||null; out.push({name,duration,eligibility}); } return out;}
for(const [label,file] of [['"'ug','jnu-ug.html'],['pg','jnu-pg.html'],['dip','jnu-diploma.html'],['dist','jnu-distance.html'],['online','jnu-online.html']]){const a=parsePage(file); console.log(label,a.length); console.log(JSON.stringify(a.slice(0,5),null,2)); console.log(JSON.stringify(a.slice(-3),null,2));}
NODE"

