function dec(s){return s.replace(/&amp;/g,'&').replace(/&#39;|&#x27;|&#039;/g,\"'\").replace(/&nbsp;/g,' ').replace(/&ndash;/g,'–').replace(/&mdash;/g,'—').replace(/&rsquo;/g,'’').replace(/&ldquo;|&rdquo;/g,'\"').replace(/&lt;/g,'<').replace(/&gt;/g,'>');}
function clean(s){return dec(s.replace(/<script[\\s\\S]*?<\\/script>/gi,' ').replace(/<style[\\s\\S]*?<\\/style>/gi,' ').replace(/<["'^>]+>/g,'"' ')).replace(/[\\t\\r\\n ]+/g,' ').trim();}
function htmlFile(n){return fs.readFileSync(path.join(base,n),'utf8');}
function extractDurationEligibility(block){
  const dm=block.match(/Duration:\\s*(.*?)(?=Eligibility:|Selection Procedure:|Tuition Fee:|Caution Money:|Apply Online|View Details|How to apply|"'$)/i);
  const em=block.match(/Eligibility:'"\\s*(.*?)(?=Selection Procedure:|Tuition Fee:|Caution Money:|Apply Online|View Details|How to apply|"'$)/i);
  return {duration:dm?.[1]?.trim()||null,eligibility:em?.[1]?.trim()||null};
}
function parseNumbered(file, catalogUrl, mode){
  const html=htmlFile(file);
  const hs=[...html.matchAll(/<h[3-6][''^>]*>(['"\\s\\S]*?)<\\/h[3-6]>/gi)].filter(m=>/"'^'"\\s*\\d+\\./.test(clean(m[1])));
  return hs.map((m,i)=>{
    const name=clean(m[1].replace(/<span[\\s\\S]*?<\\/span>/gi,' ')).replace(/"'^'"\\d+\\.\\s*/,'' );
    const start=m.index+m[0].length, end=i+1<hs.length?hs[i+1].index:html.length;
    const raw=html.slice(start,end), info=extractDurationEligibility(clean(raw));
    const href=(m[1].match(/href=[\"'](https:\\/\\/www\\.jnujaipur\\.ac\\.in\\/programmes\\/["'^"'"']+)[\"']/i)||[])[1]||catalogUrl;
    return {name,duration:info.duration,eligibility:info.eligibility,official_course_url:href,mode,source:'category'};
  });
}
function parseDetail(id,url,mode){
  const html=htmlFile("'`jnu-detail-${id}.html`);
